import math
from typing import List

class Solution:
    def maximumAmount(self, coins: List[List[int]]) -> int:
        m, n = len(coins), len(coins[0])

        # Space optimization: keep track of the DP state for the previous row
        # dp[j][k] will store the maximum coins at column j with k neutralizations
        dp = [[-math.inf] * 3 for _ in range(n)]

        # Base case for the starting cell
        if coins[0][0] >= 0:
            dp[0][0] = coins[0][0]
        else:
            dp[0][0] = coins[0][0]
            dp[0][1] = 0

        for i in range(m):
            next_dp = [[-math.inf] * 3 for _ in range(n)]
            for j in range(n):
                if i == 0 and j == 0:
                    # Inherit base case if we're at the start
                    next_dp[0][0] = dp[0][0]
                    next_dp[0][1] = dp[0][1]
                    next_dp[0][2] = dp[0][2]
                    continue

                for k in range(3):
                    # 1. Option: Do not use a neutralization on the current cell
                    best_prev = -math.inf
                    if i > 0:
                        best_prev = max(best_prev, dp[j][k])
                    if j > 0:
                        best_prev = max(best_prev, next_dp[j-1][k])

                    if best_prev != -math.inf:
                        next_dp[j][k] = max(next_dp[j][k], best_prev + coins[i][j])

                    # 2. Option: Use a neutralization on the current cell (if possible and needed)
                    if k > 0 and coins[i][j] < 0:
                        best_prev_k1 = -math.inf
                        if i > 0:
                            best_prev_k1 = max(best_prev_k1, dp[j][k-1])
                        if j > 0:
                            best_prev_k1 = max(best_prev_k1, next_dp[j-1][k-1])

                        if best_prev_k1 != -math.inf:
                            next_dp[j][k] = max(next_dp[j][k], best_prev_k1)

            dp = next_dp

        return int(max(dp[n-1]))

